 oshirish → y ni oshirish; yakun (60;40).","options":[{"id":"dbfd960b-5853-55e2-95ce-e222bca8d5e9","side":"a","content":"change y by (40)","order_idx":0},{"id":"4ecbbf04-93ca-5bc3-b4e6-0152a2ac4c3d","side":"a","content":"change x by (60)","order_idx":1},{"id":"044025c6-2a48-53d9-a9fc-d2b315626081","side":"a","content":"go to x: (0) y: (0)","order_idx":2},{"id":"ef5b0ccc-d3da-5290-8fbd-d09170c64d66","side":"a","content":"when green flag clicked","order_idx":3}],"answer_key":{"order":["ef5b0ccc-d3da-5290-8fbd-d09170c64d66","044025c6-2a48-53d9-a9fc-d2b315626081","4ecbbf04-93ca-5bc3-b4e6-0152a2ac4c3d","dbfd960b-5853-55e2-95ce-e222bca8d5e9"]}},{"id":"SL3-Y3-01-02","qid":"32cbeab2-9b55-58cc-9dde-e5253b689e0b","lesson_id":"97000000-0000-4000-8000-000000000001","construct_code":null,"construct_id":"55eb8372-7378-437a-99ed-ffc77bd5fc4c","group_code":"S4.BLOCK","format":"Y3","stem":"Sprayt sahnada birinchi kostyumini ko‘rsatib, 1 soniyadan keyin ikkinchi kostyumga o‘tadigan skriptni tartiblang.","difficulty":3,"cognitive":"mulohaza","source":"ICT 5-sinf (2020), PDF 86–100; Cambridge+ 5-sinf, PDF 76–89; spetsifikatsiya, PDF 4","scope":"CORE","why":"Dastlab kostyum tanlanadi, kutishdan so‘ng keyingisi ko‘rsatiladi.","options":[{"id":"7e65dc50-f846-5692-af73-c63c93bbeee4","side":"a","content":"switch costume to [costume1]","order_idx":0},{"id":"c100ed28-8ced-5b0a-9d83-ba8488b6fa38","side":"a","content":"when green flag clicked","order_idx":1},{"id":"9d8438b2-013d-5146-91c9-eaaeab0ec444","side":"a","content":"wait (1) seconds","order_idx":2},{"id":"8a85223d-d690-5c99-acfb-f46787ccb0e2","side":"a","content":"next costume","order_idx":3}],"answer_key":{"order":["c100ed28-8ced-5b0a-9d83-ba8488b6fa38","7e65dc50-f846-5692-af73-c63c93bbeee4","9d8438b2-013d-5146-91c9-eaaeab0ec444","8a85223d-d690-5c99-acfb-f46787ccb0e2"]}}]$SL31$::jsonb;
 q jsonb; opt jsonb; mid uuid; cid uuid; qid uuid; existing integer;
BEGIN
 SELECT id INTO STRICT mid FROM public.modules WHERE code='M07';
 FOR q IN SELECT value FROM jsonb_array_elements(data) LOOP
   qid := (q->>'qid')::uuid;
   SELECT COUNT(*) INTO existing FROM public.questions WHERE id=qid;
   IF existing > 0 THEN
      IF NOT EXISTS (SELECT 1 FROM public.questions x WHERE x.id=qid AND x.source_reference LIKE 'Scratch-LOGO-2026-v3.1:'||(q->>'id')||'%' AND x.format=(q->>'format')::question_format) THEN
         RAISE EXCEPTION 'Unexpected question id collision %',qid;
      END IF;
      CONTINUE;
   END IF;
   SELECT c.id INTO STRICT cid FROM public.constructs c
    WHERE c.code=COALESCE(q->>'construct_code',(SELECT code FROM public.constructs WHERE id=(q->>'construct_id')::uuid))
       AND c.is_active=true;
   IF NOT EXISTS (SELECT 1 FROM public.lessons l WHERE l.id=(q->>'lesson_id')::uuid AND l.module_id=mid AND l.status='published') THEN
      RAISE EXCEPTION 'M07 published lesson missing for %',q->>'id';
   END IF;
   INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference,source_lesson_id)
   SELECT qid,m.subject_id,cid,q->>'group_code',(q->>'format')::question_format,(q->>'cognitive')::cognitive_level,
       (q->>'difficulty')::int,q->>'stem','[]'::jsonb,false,'review'::content_status,
       'Scratch-LOGO-2026-v3.1:'||(q->>'id')||'; source='||(q->>'source')||'; scope='||(q->>'scope'),(q->>'lesson_id')::uuid
   FROM public.modules m WHERE m.id=mid;
   FOR opt IN SELECT value FROM jsonb_array_elements(q->'options') LOOP
     INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
       VALUES ((opt->>'id')::uuid,qid,(opt->>'side')::character,(opt->>'order_idx')::int,opt->>'content')
       ON CONFLICT(id) DO NOTHING;
   END LOOP;
   INSERT INTO public.question_keys(question_id,payload,explanation_md)
   VALUES(qid,q->'answer_key', (q->>'why')||E'\n\nManba: '||(q->>'source')||E'\nTahrir: ta’limiy sintez; ekspert auditi tavsiya etiladi.')
   ON CONFLICT(question_id) DO NOTHING;
 END LOOP;
END $do$;


