"repeat (4) { move (40); turn (90) }","order_idx":0},{"id":"8eea8f3b-5dee-5cd5-8fb6-0dd266b687a4","side":"a","content":"erase all","order_idx":1},{"id":"5b0fc2c9-2ae4-52e7-b359-89613f0110df","side":"a","content":"pen down","order_idx":2},{"id":"3425c06d-0957-5557-ae98-7b36609cd5fc","side":"a","content":"turn (45); repeat (4) { move (40); turn (90) }","order_idx":3}],"answer_key":{"order":["8eea8f3b-5dee-5cd5-8fb6-0dd266b687a4","5b0fc2c9-2ae4-52e7-b359-89613f0110df","5dcc333f-f2a7-5dbe-8b09-14efce093425","3425c06d-0957-5557-ae98-7b36609cd5fc"]}},{"id":"SL3-Y3-11-02","qid":"1df091ca-8352-5289-97e0-debae3b6f037","lesson_id":"4ca462ee-0503-5352-ab44-e5bb4ff495a8","construct_code":null,"construct_id":"15614f33-3e9d-4ac6-825f-64617661c946","group_code":"S4.BLOCK","format":"Y3","stem":"Scratch Pen bilan qalam qalinligini o‘zgartirib, keyin chiziq chizish tartibini aniqlang.","difficulty":3,"cognitive":"mulohaza","source":"ICT 5-sinf (2020), PDF 103–107; Cambridge+ 6-sinf, PDF 125–143","scope":"CORE","why":"Avval iz tozalanadi, qalinlik belgilanadi, qalam tushiriladi va yurish iz qoldiradi.","options":[{"id":"bbe83c36-fd03-5a4a-9dd7-3030d955881c","side":"a","content":"pen down","order_idx":0},{"id":"5c109f03-7259-5086-9961-af1af848c761","side":"a","content":"move (80) steps","order_idx":1},{"id":"3113aa54-248e-569a-b872-ebaa818dfa2e","side":"a","content":"set pen size to (6)","order_idx":2},{"id":"ec1b6ade-e825-5628-94ff-d1247e7c5a89","side":"a","content":"erase all","order_idx":3}],"answer_key":{"order":["ec1b6ade-e825-5628-94ff-d1247e7c5a89","3113aa54-248e-569a-b872-ebaa818dfa2e","bbe83c36-fd03-5a4a-9dd7-3030d955881c","5c109f03-7259-5086-9961-af1af848c761"]}}]$SL31$::jsonb;
 q jsonb; opt jsonb; mid uuid; cid uuid; qid uuid; existing integer;
BEGIN
 SELECT id INTO STRICT mid FROM public.modules WHERE code='M07';
 FOR q IN SELECT value FROM jsonb_array_elements(data) LOOP
   qid := (q->>'qid')::uuid;
   SELECT COUNT(*) INTO existing FROM public.questions WHERE id=qid;
   IF existing > 0 THEN
      IF NOT EXISTS (SELECT 1 FROM public.questions x WHERE x.id=qid AND x.source_reference LIKE 'Scratch-LOGO-2026-v3.1:'||(q->>'id')||'%' AND x.format=(q->>'format')::question_format) THEN
         RAISE EXCEPTION 'Unexpected question id collision %',qid;
      END IF;
      CONTINUE;
   END IF;
   SELECT c.id INTO STRICT cid FROM public.constructs c
    WHERE c.code=COALESCE(q->>'construct_code',(SELECT code FROM public.constructs WHERE id=(q->>'construct_id')::uuid))
       AND c.is_active=true;
   IF NOT EXISTS (SELECT 1 FROM public.lessons l WHERE l.id=(q->>'lesson_id')::uuid AND l.module_id=mid AND l.status='published') THEN
      RAISE EXCEPTION 'M07 published lesson missing for %',q->>'id';
   END IF;
   INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference,source_lesson_id)
   SELECT qid,m.subject_id,cid,q->>'group_code',(q->>'format')::question_format,(q->>'cognitive')::cognitive_level,
       (q->>'difficulty')::int,q->>'stem','[]'::jsonb,false,'review'::content_status,
       'Scratch-LOGO-2026-v3.1:'||(q->>'id')||'; source='||(q->>'source')||'; scope='||(q->>'scope'),(q->>'lesson_id')::uuid
   FROM public.modules m WHERE m.id=mid;
   FOR opt IN SELECT value FROM jsonb_array_elements(q->'options') LOOP
     INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
       VALUES ((opt->>'id')::uuid,qid,(opt->>'side')::character,(opt->>'order_idx')::int,opt->>'content')
       ON CONFLICT(id) DO NOTHING;
   END LOOP;
   INSERT INTO public.question_keys(question_id,payload,explanation_md)
   VALUES(qid,q->'answer_key', (q->>'why')||E'\n\nManba: '||(q->>'source')||E'\nTahrir: ta’limiy sintez; ekspert auditi tavsiya etiladi.')
   ON CONFLICT(question_id) DO NOTHING;
 END LOOP;
END $do$;


